<?php if(!empty($installment_groups)){ ?><h3>Parcelamentos vinculados</h3><div class="table-responsive"><table class="table"><thead><tr><th>Fatura</th><th>Grupo</th><th>Conta / ambiente</th><th></th></tr></thead><tbody><?php foreach($installment_groups as $group){ ?><tr><td>#<?= (int)$group['invoice_id']; ?></td><td><?= $e($group['batch_id']); ?></td><td><?= $e($group['account_id'].' · '.$environmentLabel($group['environment'])); ?></td><td><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['action'=>'open_installment_group','group_origin'=>$group['id'],'company_asaas_preferences_csrf'=>$preferences_csrf]); ?><button class="btn btn-default btn-sm" type="submit">Ver parcelas</button></form></td></tr><?php } ?></tbody></table></div><?php } ?>
<?php if(($installment_panel??null)!==null){ ?><h4>Parcelas de <?= $e($installment_panel['group_id']); ?></h4><p>Cada confirmação registra somente o principal da parcela recebida. Tarifas observadas não são despesas contabilizadas. Nenhuma cobrança é enviada por esta ação.</p><div class="table-responsive"><table class="table"><thead><tr><th>Parcela</th><th>Cobrança</th><th>Vencimento</th><th>Valor</th><th>Situação consultada</th><th>Recebimento</th><th>Ações</th></tr></thead><tbody><?php foreach($installment_panel['members'] as $member){ ?><tr><td><?= (int)$member['number']; ?></td><td><?= $e($member['id']); ?></td><td><?= $e($member['due_date']); ?></td><td><?= $e($member['value']); ?></td><td><?= $e($member['status']); ?></td><td><?= $member['payment_id']===null?'—':'#'.(int)$member['payment_id']; ?></td><td><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['group_origin'=>$installment_panel['origin_id'],'remote_id'=>$member['id'],'company_asaas_preferences_csrf'=>$preferences_csrf]); ?><button class="btn btn-default btn-sm" name="action" value="observe_installment" type="submit">Consultar</button><?php if(($can_settle??false)&&$member['payment_id']===null&&empty($member['removal'])){ ?><label><input type="checkbox" name="confirm" value="1"> Confirmo o recebimento desta parcela</label><button class="btn btn-primary btn-sm" name="action" value="reconcile_installment" type="submit">Consultar e conciliar</button><?php } ?></form><?php if(($can_refund??false)&&$member['payment_id']!==null&&$member['billing_type']==='PIX'&&isset($member['origin_id'])){ ?><a class="btn btn-default btn-sm" href="<?= $e($action_url.(str_contains($action_url,'?')?'&':'?').'refund_origin='.(int)$member['origin_id']); ?>#asaas-refunds">Reembolso desta parcela</a><?php } ?><?php if(($can_remove??false)&&$member['payment_id']===null&&(!empty($member['removal'])||in_array($member['status'],['PENDING','OVERDUE'],true))){ ?><form method="post" action="<?= $e($action_url); ?>#monitor"><?php $hidden(['group_origin'=>$installment_panel['origin_id'],'remote_id'=>$member['id'],'company_asaas_preferences_csrf'=>$preferences_csrf]); ?><?php if(empty($member['removal'])){ ?><label><input type="checkbox" name="confirm" value="1"> Confirmo excluir somente esta parcela no Asaas</label><button class="btn btn-danger btn-sm" name="action" value="remove_installment" type="submit">Excluir parcela</button><?php }else{ ?><p><?= $e($member['removal']['state']); ?></p><button class="btn btn-default btn-sm" name="action" value="refresh_installment_removal" type="submit">Conferir exclusão</button><?php } ?></form><?php } ?></td></tr><?php } ?></tbody></table></div><?php } ?>
